def c_atoi(s):
    # C atoi semantics: skip leading whitespace (space, \t, \n, \v, \f, \r), optional +/- , then digits
    if s is None:
        return 0
    s = str(s)
    i = 0
    n = len(s)
    while i < n and s[i] in ' \t\n\v\f\r':
        i += 1
    sign = 1
    if i < n and s[i] in '+-':
        if s[i] == '-':
            sign = -1
        i += 1
    val = 0
    found = False
    while i < n and s[i].isdigit():
        # Handle ASCII digits only? C isdigit is ASCII 0-9. Python isdigit includes unicode? Use '0'<=c<='9'
        if '0' <= s[i] <= '9':
            val = val*10 + (ord(s[i])-ord('0'))
            found = True
            i += 1
        else:
            break
    if not found:
        return 0
    return sign * val

def c_atof(s):
    # C atof: parse float, return 0.0 if invalid
    if s is None:
        return 0.0
    s = str(s).strip()
    if not s:
        return 0.0
    try:
        # Python float handles most, but C atof stops at first invalid char, e.g., "1.2abc" -> 1.2, "abc" -> 0.0
        # Use regex to extract leading float
        import re
        m = re.match(r'^[ \t\n\v\f\r]*[+-]?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?', str(s))
        if not m:
            return 0.0
        return float(m.group(0).strip())
    except:
        return 0.0

