# Index implementation
import time as time_module

def index_traverse_one(root_abs, buckets, topn_count, max_depth, filter_uid, fs_exclude, fs_include, excludes, check_hard, one_fs, hide_names, seen_hard, is_verbose, is_debug, is_quiet, show_progress, err_print):
    import os as osmod
    import stat as statmod
    hist = {}
    topn_all = []
    # Check root is dir (follow symlink for root)
    try:
        st_follow = osmod.stat(root_abs)
        if not statmod.S_ISDIR(st_follow.st_mode):
            if not is_quiet:
                err_print(f"skipping {root_abs}: Not a directory")
            return (0, 0, 0, 0, {}, [], [])
        root_dev = st_follow.st_dev
    except Exception:
        if not is_quiet:
            err_print(f"skipping {root_abs}: Not a directory")
        return (0, 0, 0, 0, {}, [], [])
    try:
        root_fst = get_fstype(root_abs)
    except:
        root_fst = None
    if is_debug:
        err_print(f">> {root_abs}")
    def is_excluded(base):
        for pat in excludes:
            try:
                if fnmatch.fnmatch(base, pat):
                    return True
            except:
                pass
        return False
    # Recursive
    def traverse_dir(abs_path, depth, is_root):
        children = []
        try:
            with osmod.scandir(abs_path) as it:
                entries = list(it)
        except OSError as e:
            msg = osmod.strerror(e.errno) if getattr(e, 'errno', None) else "Permission denied"
            if not is_quiet:
                err_print(f"skipping {abs_path}: {msg}")
            return None
        for entry in entries:
            full = entry.path
            base = entry.name
            if is_excluded(base):
                if not is_quiet:
                    err_print(f"skipping {full}: Excluded by user")
                continue
            try:
                st = osmod.lstat(full)
            except OSError as e:
                msg = osmod.strerror(e.errno) if getattr(e, 'errno', None) else "Permission denied"
                if not is_quiet:
                    err_print(f"skipping {full}: {msg}")
                continue
            if filter_uid is not None and st.st_uid != filter_uid:
                continue
            if fs_exclude or fs_include:
                try:
                    fst = get_fstype(full)
                except:
                    fst = 'unknown'
                if fs_exclude and fst in fs_exclude:
                    if not is_quiet:
                        err_print(f"skipping {full}: File system type '{fst}' is excluded")
                    continue
                if fs_include and fst not in fs_include:
                    if fst != root_fst:
                        if not is_quiet:
                            err_print(f"skipping {full}: File system type '{fst}' is not included")
                        continue
            mode = st.st_mode
            is_dir = statmod.S_ISDIR(mode)
            if is_dir:
                if one_fs and st.st_dev != root_dev:
                    if not is_quiet:
                        err_print(f"skipping {full}: Not crossing file system boundaries")
                    continue
                if is_debug:
                    err_print(f">> {base}")
                child = traverse_dir(full, depth+1, False)
                if child is None:
                    continue
                children.append(child)
                if is_debug:
                    err_print(f"<< {base} actual:{child['size_app']} apparent:{child['size_act']}")
            else:
                if check_hard:
                    key = (st.st_dev, st.st_ino)
                    if key in seen_hard:
                        continue
                    seen_hard.add(key)
                apparent = st.st_size
                try:
                    actual = st.st_blocks * 512
                except AttributeError:
                    actual = 0
                if is_debug:
                    err_print(f"    {apparent} {actual} {base}")
                # hist
                if apparent <= 1:
                    bkt = 0
                else:
                    bkt = apparent.bit_length() - 1
                if bkt < 0:
                    bkt = 0
                if bkt >= buckets:
                    if not is_quiet:
                        err_print(f"File sizes large enough we ran out of histogram buckets {buckets}, please increase the number of buckets and re-run your indexing.")
                else:
                    hist[bkt] = hist.get(bkt, 0) + 1
                topn_all.append((apparent, actual, full))
                ftype = 'file'
                if statmod.S_ISLNK(mode):
                    ftype = 'symlink'
                elif statmod.S_ISFIFO(mode):
                    ftype = 'fifo'
                elif statmod.S_ISSOCK(mode):
                    ftype = 'socket'
                elif statmod.S_ISCHR(mode) or statmod.S_ISBLK(mode):
                    ftype = 'device'
                else:
                    ftype = 'file'
                stored_name = '<FILE>' if hide_names else base
                stored_full = os.path.join(abs_path, '<FILE>') if hide_names else full
                stored_flag = (max_depth == 0 or depth < max_depth)
                node = {'abs_path': full, 'stored_full': stored_full, 'stored_parent': abs_path, 'name': base, 'stored_name': stored_name, 'depth': depth+1, 'parent_depth': depth, 'type': ftype, 'size_app': apparent, 'size_act': actual, 'count': 1, 'children': [], 'is_dir': False, 'stored': stored_flag}
                children.append(node)
        total_app = sum(c['size_app'] for c in children)
        total_act = sum(c['size_act'] for c in children)
        if is_root:
            total_count = sum(c['count'] for c in children)
        else:
            total_count = 1 + sum(c['count'] for c in children)
        node = {'abs_path': abs_path, 'stored_full': abs_path, 'stored_parent': os.path.dirname(abs_path.rstrip('/')) if abs_path!='/' else '/', 'name': os.path.basename(abs_path.rstrip('/')) if abs_path!='/' else '/', 'stored_name': os.path.basename(abs_path.rstrip('/')) if abs_path!='/' else '/', 'depth': depth, 'parent_depth': depth-1 if depth>0 else -1, 'type': 'dir', 'size_app': total_app, 'size_act': total_act, 'count': total_count, 'children': children, 'is_dir': True, 'stored': True if is_root else (max_depth==0 or depth < max_depth)}
        return node
    root_node = traverse_dir(root_abs, 0, True)
    if root_node is None:
        if is_debug:
            err_print(f"<< {root_abs} actual:0 apparent:0")
        return (0, 1, 0, 0, {}, [], [])
    if is_debug:
        err_print(f"<< {root_abs} actual:{root_node['size_app']} apparent:{root_node['size_act']}")
    trav_files = 0
    trav_dirs = 0
    stored_entries = []
    def walk(n, is_root_n=False):
        nonlocal trav_files, trav_dirs
        if n['is_dir']:
            trav_dirs += 1
            if not is_root_n and n.get('stored', True):
                parent = os.path.dirname(n['abs_path'].rstrip('/'))
                if parent == '':
                    parent = '/'
                stored_entries.append((n['abs_path'], parent, n['stored_name'], 'dir', n['size_app'], n['size_act'], n['count']))
            for ch in n['children']:
                walk(ch, False)
        else:
            trav_files += 1
            if n.get('stored', True):
                stored_entries.append((n['stored_full'], n['stored_parent'], n['stored_name'], n['type'], n['size_app'], n['size_act'], n['count']))
    walk(root_node, True)
    filtered = [x for x in topn_all if x[0] > 10240]
    filtered.sort(key=lambda x: (-x[0], x[2]))
    if topn_count is None:
        topn_count = 10
    if topn_count < 0:
        topn_count = 0
    topn_store = filtered[:topn_count] if topn_count>0 else []
    return (trav_files, trav_dirs, root_node['size_app'], root_node['size_act'], hist, topn_store, stored_entries)

