                if one_fs and st.st_dev != root_dev:
                    if not is_quiet:
                        err_print(f"skipping {full}: Not crossing file system boundaries")
                    continue
                if is_debug:
                    err_print(f">> {base}")
                child = traverse_dir(full, depth+1, False)
                if child is None:
                    continue
                children.append(child)
                if is_debug:
                    err_print(f"<< {base} actual:{child['size_app']} apparent:{child['size_act']}")
            else:
                if check_hard:
                    key = (st.st_dev, st.st_ino)
                    if key in seen_hard:
                        continue
                    seen_hard.add(key)
