def resolve_db_path(cmd_opts, config_opts):
    # Precedence: cmdline database > config database > env DUC_DATABASE > default
    if 'database' in cmd_opts:
        return cmd_opts['database']
    if 'database' in config_opts:
        return config_opts['database']
    env = os.environ.get('DUC_DATABASE')
    if env:
        return env
    return get_default_db()

